    Element child = el;
    for (Element parent = el.parent(); parent != null && !parent.nameIs("#root"); child = parent, parent = parent.parent()) {
        if (parent.nameIs("fieldset") && parent.hasAttr("disabled")) {
            // find the first legend child of this fieldset that is an ancestor-or-self of the control
            boolean inFirstLegend = false;
            for (Element legendChild = child; legendChild.parent() == parent; ) {
                if (legendChild.nameIs("legend") && legendChild.elementSiblingIndex() == 0) {
                    inFirstLegend = true;
                    break;
                }
                Element ancestor = legendChild.parent();
                if (ancestor == parent) break;
                legendChild = ancestor;
            }
            if (!inFirstLegend) return true;
            // exempt by the legend: keep climbing — an outer disabled fieldset may still apply
        }
    }
    return false;
}

