93	    /**
94	     Get the data that this form submits. The returned list is computed fresh from the form's associated controls in
95	     document order, on every call, and is independent of the DOM: modifying the list does not change the document, and
96	     controls sharing a name each contribute their own entry.
97	     <p>The controls are filtered following the HTML form submission rules:</p>
98	     <ul>
99	     <li>controls that are themselves {@code disabled}, or that are inside a {@code disabled} {@code <fieldset>}, are
100	     skipped — except for controls inside that fieldset's first {@code <legend>}; a nested disabled fieldset is not
101	     re-enabled by an outer fieldset's legend;</li>
102	     <li>a single-selection {@code <select>} submits the first enabled selected option, or, when nothing is selected, the
103	     first enabled option; if there is no enabled option, it submits nothing;</li>
104	     <li>a {@code multiple} {@code <select>} submits every enabled selected option in order, and nothing if there are
105	     none;</li>
106	     <li>{@code <option>}s that are disabled, or that are within a disabled {@code <optgroup>}, are not eligible;</li>
107	     <li>checkboxes and radio buttons are only included when checked;</li>
108	     <li>{@code <input>} elements of type {@code button} and {@code image}, and {@code <button>} elements, are not
109	     submitted; other input types (including {@code submit} and {@code reset}) are included as before.</li>
110	     </ul>
111	     @return a fresh, independent list of key vals
112	     */
113	    public List<Connection.KeyVal> formData() {
114	        ArrayList<Connection.KeyVal> data = new ArrayList<>();
115	
116	        // iterate the form control elements and accumulate their values
117	        for (Element el: elements()) {
118	            if (!el.tag().isFormSubmittable()) continue; // contents are form listable, superset of submitable
119	            if (el.nameIs("button")) continue; // <button> elements are never serialized by jsoup
120	            if (el.hasAttr("disabled")) continue; // skip disabled form inputs
121	            if (inDisabledFieldset(el)) continue; // skip controls in a disabled fieldset (first legend excepted)
122	            String name = el.attr("name");
123	            if (name.length() == 0) continue;
124	            String type = el.attr("type");
125	
126	            if (type.equalsIgnoreCase("button") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these
127	
128	            if (el.nameIs("select")) {
129	                boolean multiple = el.hasAttr("multiple");
130	                Elements selected = el.select("option[selected]");
131	                if (!selected.isEmpty()) {
132	                    if (multiple) {
133	                        for (Element option : selected) {
134	                            if (isEnabledOption(option))
135	                                data.add(HttpConnection.KeyVal.create(name, option.val()));
136	                        }
137	                    } else {
138	                        // single select: only the first enabled selected option counts
139	                        for (Element option : selected) {
140	                            if (isEnabledOption(option)) {
141	                                data.add(HttpConnection.KeyVal.create(name, option.val()));
142	                                break;
143	                            }
144	                        }
145	                    }
146	                } else if (!multiple) {
147	                    // nothing marked selected: a single select defaults to its first enabled option
148	                    for (Element option : el.select("option")) {
149	                        if (isEnabledOption(option)) {
150	                            data.add(HttpConnection.KeyVal.create(name, option.val()));
151	                            break;
152	                        }
153	                    }
154	                }
155	                // a multiple select with no enabled selected option submits nothing
156	            } else if ("checkbox".equalsIgnoreCase(type) || "radio".equalsIgnoreCase(type)) {
157	                // only add checkbox or radio if they have the checked attribute
158	                if (el.hasAttr("checked")) {
159	                    final String val = el.val().length() >  0 ? el.val() : "on";
160	                    data.add(HttpConnection.KeyVal.create(name, val));
161	                }
162	            } else {
163	                data.add(HttpConnection.KeyVal.create(name, el.val()));
164	            }
165	        }
166	        return data;
167	    }
168	
169	    /**
170	     Check if a control is excluded by a disabled ancestor fieldset. A disabled fieldset disables its descendants,
171	     except for those inside its first {@code legend} child's subtree. A nested disabled fieldset stays disabled even
172	     when it sits within an outer fieldset's exempt legend.
173	     @param el the control to check
174	     @return true if the control is within a disabled fieldset without an exempting legend
175	     */
176	    private static boolean inDisabledFieldset(Element el) {
177	        Element child = el;
178	        for (Element parent = el.parent(); parent != null && !parent.nameIs("#root"); child = parent, parent = parent.parent()) {
179	            if (parent.nameIs("fieldset") && parent.hasAttr("disabled") && !isFirstLegendChild(child, parent))
180	                return true;
181	            // if exempted by this fieldset's first legend, keep climbing — an outer disabled fieldset may still apply
182	        }
183	        return false;
184	    }
185	
186	    /**
187	     Check if {@code child} is the first {@code legend} child of {@code fieldset}; the subtree of that legend is
188	     exempted from the fieldset's disabled state.
189	     */
190	    private static boolean isFirstLegendChild(Element child, Element fieldset) {
191	        if (!child.nameIs("legend")) return false;
192	        for (Element fieldsetChild : fieldset.children()) {
193	            if (fieldsetChild.nameIs("legend")) return fieldsetChild == child; // first legend encountered in tree order
194	        }
195	        return false;
196	    }
197	
198	    /**
199	     Check if an option is eligible for submission: not itself disabled, and not inside a disabled optgroup.
200	     @param option the option to check
201	     @return true if the option may be submitted
202	     */
203	    private static boolean isEnabledOption(Element option) {
204	        if (!option.nameIs("option") || option.hasAttr("disabled")) return false;
205	        Element parent = option.parent();
206	        if (parent != null && parent.nameIs("optgroup") && parent.hasAttr("disabled")) return false;
207	        return true;
208	    }
209	
